using InternetPulse;
using System.Net;
using System.Net.Sockets;
using System.Diagnostics;
using System.Text;
static void Check(bool value,string message){if(!value)throw new Exception(message);}
I18n.Code="ru";Check(I18n.Amount(42_819_560_000,"MB").Replace('\u00a0',' ').Replace('\u202f',' ')=="42 819,56 МБ","Russian grouping");
I18n.Code="en";Check(I18n.Amount(42_819_560_000,"MB")=="42,819.56 MB","English grouping");Check(I18n.Amount(1_000_000_000_000,"TB")=="1.00 TB","TB decimal units");
foreach(var lang in I18n.Languages){I18n.Code=lang.Code;Check(I18n.L("Начать тест")!="Начать тест"||lang.Code=="ru","Translated start button");}
string directory=Path.Combine(Path.GetTempPath(),"InternetPulse-test-"+Guid.NewGuid());var store=new Store(directory);store.Record(4_000_000,2_000_000,DateTimeOffset.Now.AddDays(-1));store.Record(1_000_000_000,3,DateTimeOffset.Now);store.Save();Check(new Store(directory).Value.History.Count==2,"History survives restart");store.Value.History.Clear();store.Save();Check(new Store(directory).Value.History.Count==0,"Reset persists");
var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;listener.Stop();using var server=new HttpListener();server.Prefixes.Add($"http://127.0.0.1:{port}/");server.Start();using var done=new CancellationTokenSource();var handlers=new List<Task>();long serverUploaded=0;
var accept=Task.Run(async()=>{while(!done.IsCancellationRequested){try{var ctx=await server.GetContextAsync();var handler=Task.Run(async()=>{try{if(ctx.Request.Url!.AbsolutePath=="/fail"){ctx.Response.StatusCode=503;ctx.Response.Close();return;}if(ctx.Request.HttpMethod=="PUT"){byte[] bytes=new byte[65536];int n;while((n=await ctx.Request.InputStream.ReadAsync(bytes))>0)Interlocked.Add(ref serverUploaded,n);ctx.Response.StatusCode=200;ctx.Response.Close();return;}if(ctx.Request.HttpMethod=="HEAD"){ctx.Response.ContentLength64=16_777_216;ctx.Response.Close();return;}ctx.Response.ContentType="application/octet-stream";ctx.Response.ContentLength64=16_777_216;byte[] data=new byte[65536];for(int i=0;i<256;i++)await ctx.Response.OutputStream.WriteAsync(data);ctx.Response.Close();}catch(Exception ex)when(ex is HttpListenerException or IOException or ObjectDisposedException){}});lock(handlers)handlers.Add(handler);}catch(Exception ex)when(ex is HttpListenerException or ObjectDisposedException){break;}}});
using var engine=new NetworkEngine();string url=$"http://127.0.0.1:{port}/";engine.Start(url,url,1,.5,4,false);var clock=Stopwatch.StartNew();await Task.Delay(6000);await engine.Stop();double seconds=clock.Elapsed.TotalSeconds;Check(engine.Downloaded>300_000,"Download transfers payload");Check(engine.Uploaded>100_000,"Upload transfers payload");Check(engine.Downloaded*8/1e6/seconds<1.7,"Aggregate download rate");Check(engine.Uploaded*8/1e6/seconds<.8,"Aggregate upload rate");Check(serverUploaded>0,"Server received upload");Check(engine.Errors==0,"Successful fixture has no errors");var stopped=engine.Downloaded;await Task.Delay(200);Check(engine.Downloaded==stopped,"Stop joins workers");
engine.Start(url+"fail",url,1,0,1,false);await Task.Delay(3500);Check(engine.Errors is >=1 and <=3,"503 uses bounded retry backoff");Check(engine.Downloaded==0,"Error response not measured as payload");await engine.Stop();
try{engine.Start(url,url,double.NaN,0,1,false);throw new Exception("NaN accepted");}catch(ArgumentException){}Check(!NetworkEngine.ValidUrl("https://user:password@example.invalid/"),"URL credentials rejected");
done.Cancel();server.Close();await accept;Task[] pending;lock(handlers)pending=handlers.ToArray();await Task.WhenAll(pending);Directory.Delete(directory,true);Console.WriteLine("PASS: locales, TB, history, reset, simultaneous loopback transfer, aggregate rate limits, stop/restart, retry and validation");
